test_that("w2l_nest does not modify the caller's data.frame", {
  df <- data.frame(a = 1:2, b = 3:4, g = c("x", "y"))
  w2l_nest(df, cols = 1:2, by = "g")
  expect_identical(class(df), "data.frame")
  w2l_nest(iris, by = "Species")
  expect_identical(class(iris), "data.frame")
})

test_that("w2l_nest returns the expected structure", {
  res <- w2l_nest(iris, cols = 1:2, by = "Species")
  expect_identical(names(res), c("name", "Species", "data"))
  expect_equal(nrow(res), 6L)
  expect_identical(names(res$data[[1]]), c("Petal.Length", "Petal.Width", "value"))
  expect_s3_class(w2l_nest(iris, cols = 1, by = 5, out_type = "df")$data[[1]],
                  "data.frame", exact = TRUE)
})

test_that("w2l_nest empty input keeps the regular structure", {
  expect_warning(res <- w2l_nest(iris[0, ], cols = 1:2, by = "Species"), "0 rows")
  expect_identical(names(res), c("name", "Species", "data"))
  expect_equal(nrow(res), 0L)
})

test_that("w2l_nest validates its arguments", {
  expect_error(w2l_nest(iris), "`by` must be provided")
  expect_error(w2l_nest(iris, cols = 5, by = 5), "share column")
  expect_error(w2l_nest(iris, by = 5, out_type = "x"), "out_type")
  expect_error(w2l_nest(1:3, by = 1), "data.frame")
})
